CREATE TABLE users (id INT IDENTITY(1,1) PRIMARY KEY, username VARCHAR(50) NOT NULL, password VARCHAR(255) NOT NULL, email VARCHAR(100) NOT NULL, two_factor_code VARCHAR(20), created_at DATETIME DEFAULT GETDATE());
CREATE TABLE practice_areas (id INT IDENTITY(1,1) PRIMARY KEY, title VARCHAR(100) NOT NULL, description TEXT, icon VARCHAR(50) DEFAULT 'fas fa-balance-scale', created_at DATETIME DEFAULT GETDATE());
CREATE TABLE attorneys (id INT IDENTITY(1,1) PRIMARY KEY, name VARCHAR(100) NOT NULL, position VARCHAR(100), bio TEXT, image VARCHAR(255), email VARCHAR(100), phone VARCHAR(50), created_at DATETIME DEFAULT GETDATE());
CREATE TABLE messages (id INT IDENTITY(1,1) PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(100) NOT NULL, phone VARCHAR(50), subject VARCHAR(200), message TEXT NOT NULL, is_read BIT DEFAULT 0, created_at DATETIME DEFAULT GETDATE());
CREATE TABLE posts (id INT IDENTITY(1,1) PRIMARY KEY, title VARCHAR(255) NOT NULL, content TEXT NOT NULL, image VARCHAR(255), created_at DATETIME DEFAULT GETDATE(), updated_at DATETIME DEFAULT GETDATE());
CREATE TABLE settings (setting_key VARCHAR(50) PRIMARY KEY, setting_value TEXT);
CREATE TABLE case_results (id INT IDENTITY(1,1) PRIMARY KEY, title VARCHAR(255) NOT NULL, amount VARCHAR(50), case_type VARCHAR(100), description TEXT, created_at DATETIME DEFAULT GETDATE());
CREATE TABLE clients (id INT IDENTITY(1,1) PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(100) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, created_at DATETIME DEFAULT GETDATE());
CREATE TABLE newsletter_subscribers (id INT IDENTITY(1,1) PRIMARY KEY, email VARCHAR(100) NOT NULL UNIQUE, subscribed_at DATETIME DEFAULT GETDATE());
CREATE TABLE page_views (view_date DATE, page_url VARCHAR(255), views INT DEFAULT 0, PRIMARY KEY (view_date, page_url));
CREATE TABLE custom_forms (id INT IDENTITY(1,1) PRIMARY KEY, title VARCHAR(255) NOT NULL, fields_json TEXT, created_at DATETIME DEFAULT GETDATE());
CREATE TABLE audit_logs (id INT IDENTITY(1,1) PRIMARY KEY, user_id INT, action VARCHAR(255), ip_address VARCHAR(45), created_at DATETIME DEFAULT GETDATE());
CREATE TABLE appointments (id INT IDENTITY(1,1) PRIMARY KEY, name VARCHAR(100), email VARCHAR(100), phone VARCHAR(50), appointment_date DATE, appointment_time TIME, meeting_link VARCHAR(255), status VARCHAR(50) DEFAULT 'pending', created_at DATETIME DEFAULT GETDATE());
CREATE TABLE invoices (id INT IDENTITY(1,1) PRIMARY KEY, client_id INT, amount DECIMAL(10,2), description TEXT, status VARCHAR(50) DEFAULT 'unpaid', payment_gateway_used VARCHAR(50) NULL, created_at DATETIME DEFAULT GETDATE());